        "landing.stepEyebrow": "Step {n}",
        "landing.step1Title": "You set the date, and the grade you are aiming for.",
        "landing.step1Body": "A midterm in three weeks with an A in sight does not call for the same work as a test in ten days you just need to pass. Micabo starts there, and works out how many times each card has to come back.",
        "landing.step2Title": "You drop everything lying around the exam.",
        "landing.step2Body": "PDF handout, photos of the lecture, Word, PowerPoint, YouTube video, a recording of the tutorial, an Anki deck. Nothing to prepare: everything goes in as it is, and Micabo reads all of it.",
