        "landing.faq1q": "Are my courses private?",
        "landing.faq1a": "Yes. Your courses are not exposed in a catalog. By default you are the only one who sees them, and you can share one at import time, with your friends or with no one. The isolation is in the database: every request is evaluated with your identity, so there is no request that could ask for someone else's courses.",
        "landing.faq2q": "Does Micabo make things up?",
        "landing.faq2a": "It is the risk we take most seriously, because a wrong sheet does not look like a mistake. A word misread by text recognition can yield a perfectly credible and completely wrong definition. So Micabo never defines a term it is not sure about: when the context does not decide, the doubtful word simply does not appear on the sheet.",
        "landing.faq3q": "Does it work in other languages? Other school systems?",
        "landing.faq3a": "Yes. The country you study in decides the grading system and the language of the sheets. The site itself reads in English, French, German, Spanish or Turkish: you change the language at the top of the page, in the sign-up flow, or in the settings.",
        "landing.faq4q": "How much time does it take per day?",
        "landing.faq4a": "What the deadlines ask for, not a quota. The plan announces the time of each day before you start, often between ten and twenty-five minutes, more in the week of the test. A missed day shifts the work, it does not dig a hole.",
        "landing.faq6q": "What if I already use Anki?",
        "landing.faq6a": "Micabo's spaced repetition is Anki's: four buttons, the same intervals, the same steps. What Micabo adds, Anki does not do: writing the sheet and the cards from your course, laying out a plan up to the exam date, and questioning you beyond front and back. You can also import your Anki decks as they are.",
        "landing.iosEyebrow": "The iPhone app",
        "landing.iosTitleBefore": "Get Micabo",
        "landing.iosTitleAccent": "on iPhone",
        "landing.iosSubtitle": "The site is built for a desk: dropping in a PDF, fixing twenty cards in a row, laying your exams out on a calendar. A phone is for revising — and the app does that better than any page can.",
        "landing.iosCta": "Download on the App Store",
        "landing.iosCtaNote": "Same account, same courses and same plan as on the web.",
        "landing.iosPoint1Title": "Your courses follow you",
        "landing.iosPoint1Body": "Whatever you drop in from your computer is already there: the sheet, the cards and the plan up to exam day.",
        "landing.iosPoint2Title": "A session fits in a queue",
        "landing.iosPoint2Body": "One tap between opening the app and the first card. Four buttons under your thumb, and it picks up where you stopped.",
        "landing.iosPoint3Title": "Nothing gets revised twice",
        "landing.iosPoint3Body": "A card you grade on iPhone does not come back on the web the next day: both sides read the same schedule.",
        "landing.iosScreenCaption": "The review screen, exactly as it opens.",
        "landing.iosPhoneAria": "A look at the iPhone app",
