        "copy.alreadySubscribed": "You're already subscribed.",
        "legal.backHome": "Back to home",
        "legal.eyebrow": "Micabo · iPhone and site",
        "legal.updated": "Last updated: {date}.",
        "legal.updatedDate": "2 September 2026",
        "legal.privacy.metaTitle": "Privacy",
        "legal.privacy.metaDescription": "What Micabo keeps about you, on iPhone and on the site, and what you can do with it.",
        "legal.privacy.heading": "Privacy policy",
        "legal.privacy.linkLabel": "privacy policy",
        "legal.privacy.intro1": "This policy describes the data Micabo processes when you use the site [[site]] or the iPhone app (identifier {bundle}). Both clients share the same account and the same database. It also applies if you do not yet have an account and are only browsing the site.",
        "legal.privacy.intro2": "The controller is {editor}. For any question, correction or deletion: [[contact]].",
        "legal.privacy.whatTitle": "What Micabo is",
        "legal.privacy.whatBody": "Micabo turns a course (PDF, photo, document, video) into a sheet and flashcards, then brings them back before you forget them. An exam mode tightens revision as a date approaches. You can share a course with friends, or keep it to yourself.",
        "legal.privacy.dataTitle": "What data we process",
        "legal.privacy.dataAccount": "**The account.** Email address, identifiers provided by Apple or Google if you choose those sign-in methods, and a username. We do not store your password: email sign-in uses a link, not a secret we would keep.",
        "legal.privacy.dataSchool": "**The academic path.** Country of study, level, subjects, and school if you give it. This is used to write the sheet in the right language and the right system, and to show you classmates from the same school if a course is shared.",
        "legal.privacy.dataCourses": "**Your courses.** The files or links you upload, the text extracted from them, the generated sheets and cards, diagram images, exams (name, date, target grade) and the revision history (when a card comes back, how you rated it).",
        "legal.privacy.dataFriends": "**Friends.** Friend requests, your friends list, and the visibility you set on each course at import: you only, your friends, or classmates at your school. There is no public catalogue where a stranger would stumble on your sheets.",
        "legal.privacy.dataSubscription": "**The subscription.** The status of your Pro access (active, trial, cancelled), not your card number. Payment is collected by Apple on iPhone, by Stripe on the site. RevenueCat holds the right, so that the iPhone and the browser agree.",
        "legal.privacy.dataWaitlist": "**The waitlist.** If you leave your address before you have an account, we keep it to notify you of the opening, together with the page you came from. It is not linked to an account and is not visible through the app.",
        "legal.privacy.dataFeedback": "**Feedback.** If you send a bug or an idea from the app, we keep the message, the type (bug or idea), and the link to your account, so we can reply. They are kept for 24 months, then deleted. They are not used to profile you.",
        "legal.privacy.dataUsage": "**Generation usage.** A counter per day and per function (sheet, cards, explanation), without the course content. It is used to limit abuse, not to profile you.",
        "legal.privacy.dataDirectory": "**The directory.** Your username and, if you have given it, your school. That is what a friend or classmate sees, not your email or your preferences.",
        "legal.privacy.dataDevice": "**What stays on the device.** On iPhone, some pieces (occlusion images, audio for a card) may never leave the phone. Answers from the onboarding path stay on the device first, then are written to the database once the account is opened.",
        "legal.privacy.dataNoSell": "We do not sell your data. We do not show advertising. We do not train a language model on your courses, unless an explicit setting offers that one day — and that setting does not exist today.",
        "legal.privacy.whyTitle": "Why we process them",
        "legal.privacy.whyLead": "The legal bases, within the meaning of the GDPR:",
        "legal.privacy.whyContract": "**Performance of the contract** — creating the account, importing a course, writing the sheet and the cards, reviewing them, syncing iPhone and site, managing the subscription.",
        "legal.privacy.whyLegitimate": "**Legitimate interest** — securing the service, preventing abuse, diagnosing a fault, measuring the site's audience in aggregated form, and reading the feedback you send us. This interest does not come before yours: the isolation is in the database, not only in the application.",
        "legal.privacy.whyLegal": "**Legal obligation** — retaining what billing or accounting require, for the prescribed time.",
        "legal.privacy.whyConsent": "**Consent** — when you choose to share a course, open the camera, or sign in with Apple or Google.",
        "legal.privacy.accessTitle": "Who has access",
        "legal.privacy.accessBody": "Your courses are readable only by you, unless you have shared them. Every request to the database is evaluated with your identity: there is no query that can ask for someone else's courses. Feedback you send is read by the team, at [[contact]]. Nobody else has access to it from the application.",
        "legal.privacy.accessLead": "Service providers see some of the data, solely to provide the service:",
        "legal.privacy.accessSupabase": "**Supabase** (European Union, Stockholm region) — account, database, files.",
        "legal.privacy.accessVercel": "**Vercel** — hosting of the site, technical logs (IP address, URL) and audience measurement: the number of page views, the page you came from, the country and the device type, without a cookie and without an identifier that follows you. Processing may take place outside the European Union, under the provider's standard contractual clauses.",
        "legal.privacy.accessApple": "**Apple and Google** — if you sign in with them, or if you pay on the App Store.",
        "legal.privacy.accessStripe": "**Stripe** — payment on the site.",
        "legal.privacy.accessRevenuecat": "**RevenueCat** — subscription status, shared between iPhone and site.",
        "legal.privacy.accessFal": "**fal.ai and the models it calls** (today, language models, notably from Google) — the text or image of your course, for the time it takes to write the sheet or the cards. They are not allowed to use it for anything other than that generation.",
        "legal.privacy.accessYoutube": "**YouTube / Google** — if you import a video, we read its metadata and subtitles.",
        "legal.privacy.accessTransfer": "Some of these providers are established outside the European Union. The transfer then takes place only to provide the service, and relies on the safeguards provided by the GDPR (adequacy decision or the provider's standard contractual clauses).",
        "legal.privacy.cookiesTitle": "Cookies and trackers",
        "legal.privacy.cookiesWeb": "The site sets the cookies needed for the session (to recognise you from one page to the next once you are signed in) and an interface-language preference cookie (`micabo.ui_locale`), kept for one year, which remembers English, French, German, Spanish or Turkish. We do not set an audience-measurement cookie, nor an advertising cookie, nor cross-site tracking. The site does count its visits, but without writing anything on your device: the measurement keeps a page view, its origin, a country, a device type, and nothing that would let us recognise you from one visit to the next or on another site. That is why there is no consent banner: there is nothing to refuse on that side.",
        "legal.privacy.cookiesIos": "The iPhone does not use cookies. It keeps a session token in the device's Keychain.",
        "legal.privacy.retentionTitle": "How long we keep them",
        "legal.privacy.retentionWhile": "For as long as the account exists. Feedback is deleted after 24 months at the latest. If you delete it, from Settings on the site or in the iPhone app, or by writing to us, we erase the profile, the courses (including the extracted text), the sheets, the cards, the history, the exams, the friendships, the usage counters, the feedback and any address left on the waitlist.",
        "legal.privacy.retentionShared": "A course you have shared disappears for your friends when you delete it. A friend who has already reviewed your cards keeps their own history, not your document.",
        "legal.privacy.retentionAfter": "After deletion, providers retain what the law or their contract requires: Stripe or Apple invoices, a RevenueCat subscription identifier, technical logs (Vercel, Supabase) for a few weeks. fal.ai receives the text for the time it takes to write the sheet; we do not ask it to keep it.",
        "legal.privacy.rightsTitle": "Your rights",
        "legal.privacy.rightsBody": "You can access your data, correct it, export it, object to processing, or request erasure. To download a copy: Settings → “Download my data”. To delete the account: Settings → “Delete account”, on the site or in the iPhone app. You can also write to [[contact]]. We reply within a month.",
        "legal.privacy.rightsCnil": "You can also lodge a complaint with the CNIL (cnil.fr).",
        "legal.privacy.minorsTitle": "Minors",
        "legal.privacy.minorsBody": "Micabo is aimed at students, including those in secondary school. We do not ask for a date of birth. If you are under fifteen, use of the service must be with the agreement of a person with parental authority. We do not use a minor's data for advertising, nor for commercial profiling.",
        "legal.privacy.iosTitle": "The iPhone, in addition to the site",
        "legal.privacy.iosBody": "The app may ask for access to your photos or camera to import a course. This is not required: the site accepts an uploaded file. Notifications, if you allow them, are only used to remind you of a review. The same account opens the app and the site.",
        "legal.privacy.changesTitle": "Changes",
        "legal.privacy.changesBody": "If this policy changes in a material way, we update the date at the top of the page. Continued use after that date applies to the new version, unless the law requires a separate agreement.",
        "legal.privacy.changesAlso": "The [[terms]] complement this text.",
        "legal.terms.metaTitle": "Terms of use",
        "legal.terms.metaDescription": "The rules of the Micabo service, for iPhone and the site: account, courses, subscription, liabilities.",
        "legal.terms.heading": "Terms of use",
        "legal.terms.linkLabel": "terms of use",
        "legal.terms.intro1": "These terms govern the use of Micabo — the site [[site]] and the iPhone app ({bundle}). By creating an account or using the service, you accept them. If you do not agree, do not open an account.",
        "legal.terms.intro2": "The publisher is {editor}. Contact: [[contact]].",
        "legal.terms.serviceTitle": "The service",
        "legal.terms.serviceBody": "Micabo reads a course document you upload and writes a sheet and flashcards from it. It brings them back according to spaced repetition (the same SM-2 rule on iPhone and on the site). You can set an exam date: the revision plan then tightens towards that day. The same account opens both clients.",
        "legal.terms.servicePro": "Part of the service is available without a subscription. Pro access (courses and cards beyond the free cap, according to the offer shown at the time of purchase) is paid.",
        "legal.terms.accountTitle": "The account",
        "legal.terms.accountBody": "You can sign in with Apple, Google, or a link sent by email. You are responsible for access to your mailbox and to those third-party accounts. One account per person.",
        "legal.terms.accountDelete": "You can delete the account from Settings, on the site or in the iPhone app. This erases your courses, your cards and your history. Purchases already collected by Apple or Stripe remain subject to their refund rules.",
        "legal.terms.coursesTitle": "Your courses",
        "legal.terms.coursesOwn": "You keep ownership of what you upload. You give us only the limited, revocable right to read it, store it and transform it into a sheet and cards, to provide you the service — including by sending it to a language model for the duration of the generation.",
        "legal.terms.coursesRights": "You upload only documents you have the right to use. A handout from your teacher, your notes, a video whose import is authorised: yes. An entire copied work, someone else's assignment, illegal content: no. We may remove a course or close an account that breaks this rule.",
        "legal.terms.coursesShare": "Visibility is decided at import. A private course stays with you. A shared course is visible only to the people you have chosen (friends, or classmates at the school). This is not a library open to everyone.",
        "legal.terms.notTitle": "What Micabo is not",
        "legal.terms.notBody": "The sheet and the cards are generated automatically. They can be wrong, omit a passage, or misread a scan. Micabo is not a teacher, nor a grade guarantee. You remain responsible for what you learn and for what you submit on exam day.",
        "legal.terms.notInvent": "We try not to invent a definition when the document does not carry one. That does not make the result infallible.",
        "legal.terms.subTitle": "The subscription",
        "legal.terms.subPrices": "Prices, duration and any trial are those shown before payment. They may change for new purchases; a subscription already in progress keeps its terms until renewal.",
        "legal.terms.subIos": "**On iPhone**, payment goes through the App Store. Cancellation, renewal and refunds follow Apple's rules. Manage the subscription in your Apple account settings.",
        "legal.terms.subWeb": "**On the site**, payment goes through Stripe. Cancellation is done from the billing area indicated in the profile, or by writing to us. A trial, if offered, only becomes a charge if you let it run to the end.",
        "legal.terms.subBoth": "Pro access bought on one side applies on the other: the same account is Pro on iPhone and on the site. A payment incident may open a grace period; we do not close access in the first hour.",
        "legal.terms.forbidTitle": "What you do not do",
        "legal.terms.forbidHarm": "Use the service to harm someone, harass, or cheat in a way that violates your school's rules.",
        "legal.terms.forbidAccess": "Attempt to access another account's courses, to circumvent the isolation, or to deliberately overload the service.",
        "legal.terms.forbidResell": "Resell access, extract the service through a bot beyond normal human use, or copy Micabo to make a competing product from our generations.",
        "legal.terms.forbidIllegal": "Upload illegal or hateful content, or content that infringes someone else's privacy.",
        "legal.terms.availTitle": "Availability",
        "legal.terms.availBody": "We do our best to keep iPhone and site reachable. Maintenance, a provider outage (host, model, store) or a generation error may interrupt the service. We do not offer a guarantee of academic results, nor of uninterrupted availability.",
        "legal.terms.liabilityTitle": "Liability",
        "legal.terms.liabilityConsumer": "If you are a consumer, your statutory rights (warranty, mediation, unfair terms) apply and these terms do not set them aside.",
        "legal.terms.liabilityLimit": "Beyond that, Micabo is not liable for grades obtained, an incomplete sheet, forgetting on the day, or indirect damage (lost time, a missed exam). Our liability, if it were upheld for a breach attributable to us, is limited to the amount you paid us over the last twelve months — except in cases of gross negligence, fraud, or injury to a person's physical integrity.",
        "legal.terms.minorsTitle": "Minors",
        "legal.terms.minorsBody": "If you are under fifteen, a person with parental authority must accept these terms and supervise use. Sharing a course with friends remains your responsibility, and theirs.",
        "legal.terms.lawTitle": "Governing law",
        "legal.terms.lawBody": "These terms are governed by French law. In the event of a dispute, and after an attempt at written resolution to [[contact]], the French courts have jurisdiction — subject to any consumer-protection rules that would be more favourable to you.",
        "legal.terms.changesTitle": "Changes",
        "legal.terms.changesBody": "We may update these terms. The date at the top of the page is authoritative. A change that affects the price of a subscription in progress is announced to you before renewal.",
        "legal.terms.changesAlso": "The [[privacy]] describes the processing of your data.",
        "articles.shared.navAria": "Pages",
        "articles.shared.nextTitle": "Read next",
        "articles.shared.ctaTitle": "Drop a course, see what it becomes.",
        "articles.shared.ctaBody": "On the site and on iPhone, with the same account and the same plan.",
        "articles.method.metaTitle": "The method: spaced repetition and active recall",
        "articles.method.metaDescription": "Rereading a course does not make it stick. What you retrieve from memory does, especially if the question comes back just before you forget. How Micabo applies spaced repetition, with the real intervals.",
        "articles.method.h1": "Rereading is not enough. Remembering is.",
        "articles.method.lead1": "A page reread four times gives a feeling of mastery that does not survive the exam. What improves is recognition: “yes, I've seen this”. And recognition is not what an exam asks for.",
        "articles.method.lead2": "What holds is what you had to **retrieve from memory**, and what comes back **just before you forget it**. Two old ideas, measured for more than a century, and two ideas that are painful to apply by hand. That is all of Micabo's work.",
        "articles.method.activeTitle": "Active recall: the question before the answer",
        "articles.method.active1": "Testing yourself is more effective than rereading, even when you get it wrong. The effort of retrieval is what strengthens the trace: an answer you search for for three seconds is worth more than an answer you read in one.",
        "articles.method.active2": "That is also why a card carries **one thing to retrieve**. A card that asks for five items at once cannot be graded: you recall three, and there is no button for “three fifths”.",
        "articles.method.spacingTitle": "Spacing: coming back at the last useful moment",
        "articles.method.spacing1": "Without review, what you retain from a course falls to almost nothing in a month. Each recall resets the counter to a hundred, and the drop that follows is **slower than the previous one**. Reviewing at the right moment does not take more time: it takes less, as memory stabilizes.",
        "articles.method.spacing2": "What matters is not the shape of each curve, it is **where they split**: the first review. What spaced repetition automates is the choice of that instant, card by card.",
        "articles.method.plannerTitle": "What Micabo calculates on every rating",
        "articles.method.planner1": "Micabo schedules with **SM-2**, Anki's rule in its default settings. A new card goes through short steps, {steps}, before graduating to days. After that, each rating multiplies the interval by an ease that belongs to the card, starting at {ease} and moving with your answers.",
        "articles.method.planner2": "Four buttons, not two: “I know / I don't” does not distinguish the card retrieved with effort from the one that came on its own, and that gap is exactly what decides the next date. Here is what the four buttons announce on a new card:",
        "articles.method.buttonsCaption": "The intervals are computed by the app's scheduler, not written by hand.",
        "articles.method.planner3": "The interval is written on the button **before** you press it. A scheduler that decides on its own is quickly disobeyed: you rate “easy” to go faster, the card leaves for three weeks, and you rediscover it on exam day.",
        "articles.method.stepMinutes": "{n} min",
        "articles.method.stepJoin": ", then ",
        "articles.method.paceTitle": "Pace: what the workload asks for, not a quota",
        "articles.method.pace1": "Micabo asks neither for a number of cards per day nor for a budget of minutes. It looks at what your deadlines require today, serves all of it, and tells you how long it will take. A student sees about {seen} cards in an hour.",
        "articles.method.pace2": "There used to be a cap on new cards, calibrated on the {reps} passes a card needs before it sticks. It had one decisive flaw: three days before a midterm, it turned down cards from that very midterm in the name of the day's pace. Holding back work on the day it matters most is the wrong job.",
        "articles.method.paceNote": "What the plan spreads out are the passes until exam day. A missed day therefore leaves no hole: it shifts, and the plan is rebuilt on the next calculation.",
        "articles.method.sheetTitle": "The sheet first, the cards after",
        "articles.method.sheet1": "A card assumes you already understood. Testing yourself on a notion you have not read is learning an answer by heart without knowing what it is about: the card will be right, and the exam will not.",
        "articles.method.sheetFigure": "The dropped document becomes **a sheet**: the course put back in order, the passages that matter marked. The cards come out of it next. This is the same sheet component as in the app, on the demo course.",
        "articles.method.sheet2": "That is why Micabo first writes **the sheet** from your document: the course put back in order, the passages that matter marked. The cards are drawn from that sheet, not from the raw document. You read, then you test yourself.",
        "articles.method.sheet3": "Micabo never defines a term the document does not mention. When the context does not decide, the doubtful word does not appear on the sheet: an invented definition is perfectly credible, and that is what makes it dangerous.",
        "articles.method.formatsTitle": "Four ways to be questioned on the same sheet",
        "articles.method.formats1": "Active recall is not limited to front and back. On one sheet, Micabo asks quizzes, fill-in-the-blanks and cards, and composes graded mock exams. The questions come from your documents, and the scheduler treats them all the same way: an answer you retrieve pushes the next one further out.",
        "articles.method.formatsFigure": "A quiz is recognized by its bullets, a fill-in-the-blank by its empty line, a card by its silent front. **All four formats are drawn from the same sheet**, and graded on the same scale.",
        "articles.method.limitsTitle": "What the method does not do",
        "articles.method.limits1": "Spaced repetition places the reviews. It does not understand for you, it does not write an essay, and it does not catch up a chapter started the night before: there is no possible spacing over one night.",
        "articles.method.limits2": "It also ignores dates, by design: SM-2 does not know an exam is in three weeks. That is exactly what [[exam]] is here to fix.",
        "articles.method.examLink": "exam mode",
        "articles.exam.metaTitle": "Exam mode: set the date, the plan tightens",
        "articles.exam.metaDescription": "Spaced repetition ignores exam day. Micabo's exam mode gives it a deadline, tightens the passes as the test approaches, and stops a card from leaving past that date.",
        "articles.exam.h1": "You set the date. Micabo reorganizes everything.",
        "articles.exam.lead1": "Spaced repetition places each card at the last useful moment, indefinitely. It does not know there is an exam on the 14th. A card rated “easy” today leaves for three weeks, even if the test is in ten days, and it will not come back before.",
        "articles.exam.lead2": "Exam mode gives the scheduler what it is missing: **a deadline**, and the grade you are aiming for. You set exam day, it replans the deck around it.",
        "articles.exam.trapTitle": "Why a normal schedule gets trapped",
        "articles.exam.trap1": "A deck of two hundred cards in spaced review is perfect for continuous assessment and bad for a fixed date. Three things go wrong: some cards fall after the exam, others were never introduced, and the weakest ones come back too early to be useful on exam day.",
        "articles.exam.trap2": "The manual answer is to review the whole deck the night before. That is exactly what the method avoids: a session of three hundred cards in one evening leaves nothing the next day, and you know it before you start.",
        "articles.exam.capTitle": "No card leaves past exam day",
        "articles.exam.cap1": "This is the rule that holds everything together, and it is more radical than it looks. During an active exam, the interval a card receives is **capped at the exam date**.",
        "articles.exam.cap2": "Without this cap, the first good answer undoes the plan: the card leaves for three weeks and drops out of view. With it, it comes back one last time before exam day. The intervals shown under the buttons are therefore shorter than usual, and the session says so at the top of the screen, otherwise you would think the scheduler was broken.",
        "articles.exam.planTitle": "The plan, announced before it is applied",
        "articles.exam.plan1": "Micabo shows the projection **before** moving anything: how many cards are covered, how many passes are placed, over how many days. A replan you discover after the fact is a replan you undo.",
        "articles.exam.plan2": "The load tightens toward the end without stacking on the night before: the last passes spread over the last {days} days, staggered from one card to the next.",
        "articles.exam.dailyTitle": "Every day carries named work",
        "articles.exam.daily1": "A plan that says “review for 30 minutes” is no different from a timer. Micabo's plan says what there is to do: a quiz on chapter 3, a mock exam, an explanation out loud, a day off. You open the app, and the day is already written.",
        "articles.exam.dailyFigure": "The plan reads in the order of time, and the last line is the exam. **A missed day shifts the work, it does not dig a hole**: the plan is rebuilt on the next calculation.",
        "articles.exam.intensityTitle": "Three intensities, according to the grade you want",
        "articles.exam.intensityLead": "How many times each card should come back before the exam is not the same question for “I want to pass” and for “I want the top mark”. You set the target grade, Micabo derives the intensity:",
        "articles.exam.intensityLight": "Light",
        "articles.exam.intensityStandard": "Normal",
        "articles.exam.intensityIntense": "Intensive",
        "articles.exam.intensityPasses": "passes per card",
        "articles.exam.intensityScale": "The grade scale follows the country you study in: a French 20, a Quebec 100 and a British A-Level do not compare, and a slider that would work everywhere would mean nothing anywhere.",
        "articles.exam.severalTitle": "Several exams, several courses",
        "articles.exam.several1": "An exam covers the courses you give it, and a course can be in several exams. When two dates compete for the same card, **the nearest one** caps it: it is the first constraint, and honoring the second first would miss both.",
        "articles.exam.severalNote": "Once exam day has passed, the exam stops constraining and the deck returns to its normal schedule. Nothing to turn off: a date that has passed is no longer a date.",
        "articles.exam.limitsTitle": "What exam mode does not do",
        "articles.exam.limits1": "It does not manufacture time. Declaring an exam for tomorrow on two hundred new cards gives an honest and unsustainable plan, and Micabo shows it as it is rather than reassuring you.",
        "articles.exam.limits2": "It does not replace the method either: [[method]] do the work, exam mode only gives them a deadline. If you are coming from Anki, the [[anki]] says exactly what changes.",
        "articles.exam.methodLink": "active recall and spacing",
        "articles.exam.ankiLink": "comparison",
        "articles.anki.metaTitle": "Micabo or Anki: what actually changes",
        "articles.anki.metaDescription": "Anki is open, proven, and excellent. Micabo writes the cards from your course and replans everything around an exam date. An honest comparison, including where Anki wins.",
        "articles.anki.eyebrow": "Comparison",
        "articles.anki.h1": "Micabo or Anki: what actually changes",
        "articles.anki.lead1": "Anki is a very good program. It is open, it has twenty years of track record and a community that has documented everything. If you already use it and it works for you, you have no reason to switch.",
        "articles.anki.lead2": "The difference is not in the scheduling: **it is the same SM-2**. It is before, in the time it takes to have cards, and after, in what happens when an exam date lands.",
        "articles.anki.tableTitle": "Line by line",
        "articles.anki.tableLead": "Three lines go to Anki, and they are written as they are.",
        "articles.anki.tableCaption": "Comparison of Micabo and Anki, criterion by criterion.",
        "articles.anki.colCriterion": "Criterion",
        "articles.anki.rowAlgo": "The algorithm",
        "articles.anki.rowAlgoMicabo": "SM-2, with Anki's default settings.",
        "articles.anki.rowAlgoAnki": "SM-2 historically, FSRS today, and both can be configured.",
        "articles.anki.rowWrite": "Writing the cards",
        "articles.anki.rowWriteMicabo": "The course becomes a sheet, the sheet becomes cards. You reread and you correct.",
        "articles.anki.rowWriteAnki": "That's on you. That is where most of the time goes.",
        "articles.anki.rowDate": "An exam date",
        "articles.anki.rowDateMicabo": "The deck replans around exam day, and nothing leaves past it.",
        "articles.anki.rowDateAnki": "No notion of a deadline. You advance the deck by hand.",
        "articles.anki.rowQuestions": "Ways to be questioned",
        "articles.anki.rowQuestionsMicabo": "Cards, quizzes, fill-in-the-blanks, graded mock exams, explaining out loud.",
        "articles.anki.rowQuestionsAnki": "Front and back, and the card types you build yourself.",
        "articles.anki.rowPlatforms": "The platforms",
        "articles.anki.rowPlatformsMicabo": "iPhone and browser, the same account on both sides.",
        "articles.anki.rowPlatformsAnki": "Computer, Android, iPhone, browser.",
        "articles.anki.rowDecks": "Ready-made decks",
        "articles.anki.rowDecksMicabo": "No catalog. Your courses, and the ones your friends share.",
        "articles.anki.rowDecksAnki": "Thousands of public decks, of uneven quality.",
        "articles.anki.rowFriends": "Your classmates' courses",
        "articles.anki.rowFriendsMicabo": "A shared course is picked up in one gesture, and becomes yours.",
        "articles.anki.rowFriendsAnki": "A file to send each other.",
        "articles.anki.rowStart": "Getting started",
        "articles.anki.rowStartMicabo": "A document dropped, a sheet to read, a session that same evening.",
        "articles.anki.rowStartAnki": "Settings to understand before the first card.",
        "articles.anki.costTitle": "What Anki really costs: time",
        "articles.anki.cost1": "A useful Anki deck for a college course is two to four hours of typing per chapter: splitting, writing one question per idea, not stacking five items on a card. That work is instructive, and denying it would be dishonest. But it is the work that makes you open Anki in September and not again in November.",
        "articles.anki.costFigure": "Handout, photos, Word, PowerPoint, video, audio: **everything goes in as it is**, and so does an Anki deck. The typing disappears, the rereading stays.",
        "articles.anki.cost2": "Micabo takes that step. The course becomes a sheet put back in order, then cards drawn from that sheet. You reread, you correct what is wrong, you delete what does not help. It is still your work, but it starts at rereading instead of starting at a blank page.",
        "articles.anki.costNote": "The downside is real: a generated card can be poorly worded or drawn from a badly read scan. That is why the sheet comes before the cards, and why Micabo does not define a term the document does not mention. A sheet that is wrong does not look like a mistake.",
        "articles.anki.dateTitle": "What Anki does not do: the date",
        "articles.anki.date1": "This is the real mechanical difference. Spaced repetition places each card at the last useful moment, without end. It does not know there is an exam on the 14th: a card rated “easy” leaves for three weeks and does not come back before the test.",
        "articles.anki.date2": "In Anki, you get by advancing the deck by hand, or by reviewing everything the night before. In Micabo, you set the date and the deck replans around it, with a cap that stops a card from leaving past exam day. [[exam]] explains how.",
        "articles.anki.examLink": "Exam mode",
        "articles.anki.pickTitle": "Which one to pick",
        "articles.anki.pickAnki": "**Stay on Anki** if you like tuning your scheduler, if you want FSRS, if you are on Android, or if you want an open tool whose files you own.",
        "articles.anki.pickMicabo": "**Try Micabo** if what is blocking you is not the review but making the cards, or if your reviews are organized around exam dates rather than a continuous stream.",
        "articles.anki.pickBoth": "And if you are unsure: [[method]] is the same in both. That is what does the work, not the software that carries it.",
        "articles.anki.methodLink": "the method",
    ]

