        "landing.faq1q": "Est-ce que mes cours sont privés ?",
        "landing.faq1a": "Oui. Tes cours ne sont pas exposés dans un catalogue. Par défaut tu les vois seul, et tu peux en partager un au moment de l'import, avec tes amis ou avec personne. Le cloisonnement est dans la base : chaque requête est évaluée avec ton identité, donc il n'existe pas de requête qui puisse demander les cours de quelqu'un d'autre.",
        "landing.faq2q": "Est-ce que Micabo invente des choses ?",
        "landing.faq2a": "C'est le risque qu'on prend le plus au sérieux, parce qu'une fiche fausse ne ressemble pas à une erreur. Un mot mal lu par la reconnaissance de texte peut donner une définition parfaitement crédible et complètement fausse. Micabo ne définit donc jamais un terme dont il n'est pas sûr : quand le contexte ne tranche pas, le mot douteux n'apparaît simplement pas dans la fiche.",
        "landing.faq3q": "Ça marche dans d'autres langues ? D'autres systèmes scolaires ?",
        "landing.faq3a": "Oui. Le pays de scolarisation décide du système de notes et de la langue des fiches. Le site, lui, se lit en anglais, français, allemand, espagnol ou turc : tu changes la langue en haut de la page, dans le parcours, ou dans les réglages.",
        "landing.faq4q": "Combien de temps ça prend par jour ?",
        "landing.faq4a": "Ce que les échéances demandent, pas un quota. Le plan annonce le temps de chaque journée avant que tu commences, souvent entre dix et vingt-cinq minutes, davantage la semaine de l'épreuve. Une journée manquée décale le travail, elle ne creuse pas de trou.",
        "landing.faq6q": "Et si j'utilise déjà Anki ?",
        "landing.faq6a": "La répétition espacée de Micabo est celle d'Anki : quatre boutons, les mêmes intervalles, les mêmes paliers. Ce que Micabo ajoute, Anki ne le fait pas : écrire la fiche et les cartes à partir de ton cours, poser un plan jusqu'à la date de l'examen, et t'interroger autrement que par le recto verso. Tu peux aussi importer tes paquets Anki tels quels.",
