        "landing.iosTitleAccent": "sur iPhone",
        "landing.iosSubtitle": "Le site est fait pour le bureau : déposer un polycopié, corriger vingt cartes à la suite, poser ses examens sur un calendrier. Le téléphone, lui, sert à réviser — et c'est l'app qui le fait le mieux.",
        "landing.iosCta": "Télécharger sur l'App Store",
