        "demo.courseTitle": "Le cycle de l'eau",
        "demo.chapter": "Chapitre 4 · L'eau sur Terre",
        "demo.raw1": "Le cycle de l'eau désigne l'ensemble des mouvements de l'eau entre les océans, l'atmosphère et les continents.",
        "demo.raw2": "Sous l'effet du rayonnement solaire l'eau de surface passe à l'état de vapeur, ce phénomène est appelé évaporation et concerne surtout les océans qui couvrent 71 % de la surface terrestre.",
        "demo.raw3": "La vapeur d'eau s'élève et rencontre des couches plus froides, elle se condense alors autour de noyaux de condensation pour former des gouttelettes qui constituent les nuages.",
        "demo.raw4": "Lorsque les gouttelettes deviennent trop lourdes elles retombent sous forme de précipitations, pluie ou neige selon la température rencontrée pendant la chute.",
        "demo.raw5": "Une partie de cette eau ruisselle et rejoint les cours d'eau puis les océans, une autre s'infiltre dans le sol et alimente les nappes phréatiques.",
        "demo.sheetParagraphMarked": "L'eau change d'état sans jamais quitter la planète : ce qui s'**évapore** des océans retombe sur les continents, puis y retourne. ==71 % de l'évaporation vient des océans.==",
        "demo.sheetCallout": "Pluie ou neige ne dépend pas de l'altitude du nuage mais de la **température rencontrée pendant la chute**.",
        "demo.sheetStep1": "L'eau des océans s'évapore sous l'effet du rayonnement solaire.",
        "demo.sheetStep2": "La vapeur se condense en altitude et forme les nuages.",
        "demo.sheetStep3": "Les précipitations rendent l'eau aux continents et aux océans.",
        "demo.rivers": "Les rivières ramènent l'eau à la mer",
        "demo.sheetHighlight": "71 % de l'évaporation vient des océans.",
