        "landing.stepEyebrow": "Schritt {n}",
        "landing.step1Title": "Du nennst das Datum und die Note, die du willst.",
        "landing.step1Body": "Eine Klausur in drei Wochen mit einer Eins im Blick verlangt nicht dieselbe Arbeit wie ein Test in zehn Tagen, den du nur bestehen musst. Micabo geht davon aus und leitet ab, wie oft jede Karte zurückkommen muss.",
        "landing.step2Title": "Du legst alles ab, was rund um die Prüfung herumliegt.",
        "landing.step2Body": "PDF-Skript, Fotos der Vorlesung, Word, PowerPoint, YouTube-Video, Aufnahme des Tutoriums, Anki-Stapel. Nichts vorzubereiten: Alles kommt so rein, wie es ist, und Micabo liest alles.",
