        "landing.step3Body": "Der Stoff wird in Ordnung gebracht, die wichtigen Stellen markiert, und die Karten kommen aus diesem Blatt. Du liest nach, korrigierst, was falsch ist, und löschst, was nicht hilft.",
        "landing.step4Title": "Der Plan steht Tag für Tag, bis zum Prüfungstag.",
        "landing.step4Body": "Jeder Tag trägt eine benannte Aufgabe: ein Quiz zu Kapitel 3, eine Probeprüfung, eine Pause. Du öffnest die App und weißt, was zu tun ist. Die Last zieht sich zur Prüfung hin zusammen, und keine Karte geht darüber hinaus.",
        "landing.step5Title": "Du wirst auf vier Arten abgefragt.",
        "landing.step5Body": "Bewertete Probeprüfung, Quiz, Karten, Lückentext. Die Fragen stammen aus deinen Unterlagen, nicht aus einer allgemeinen Sammlung, und jede Antwort entscheidet über das Datum der nächsten.",
        "landing.step6Title": "Du erklärst laut, Micabo hört zu.",
