        "landing.examNote": "Verteilte Wiederholung kennt keinen Prüfungstag. Der Prüfungsmodus gibt ihr eine Frist: Die letzten Durchgänge fallen in die letzten Tage, und keine Karte geht darüber hinaus. Der Kalender unten wird vom Planer der App berechnet.",
