        "landing.footerCards": "Die Karten",
        "landing.faq1q": "Sind meine Kurse privat?",
        "landing.faq1a": "Ja. Deine Kurse stehen in keinem Katalog. Standardmäßig siehst nur du sie, und du kannst einen beim Import teilen, mit deinen Freunden oder mit niemandem. Die Trennung sitzt in der Datenbank: Jede Anfrage wird mit deiner Identität ausgewertet, also gibt es keine Anfrage, die die Kurse von jemand anderem verlangen könnte.",
        "landing.faq2q": "Erfindet Micabo Dinge?",
        "landing.faq2a": "Das ist das Risiko, das wir am ernstesten nehmen, denn ein falsches Merkblatt sieht nicht wie ein Fehler aus. Ein von der Texterkennung falsch gelesenes Wort kann eine völlig glaubwürdige und völlig falsche Definition ergeben. Micabo definiert deshalb nie einen Begriff, bei dem es sich nicht sicher ist: Wenn der Kontext nicht entscheidet, taucht das zweifelhafte Wort im Merkblatt einfach nicht auf.",
        "landing.faq3q": "Funktioniert es in anderen Sprachen? Anderen Schulsystemen?",
        "landing.faq3a": "Ja. Das Land, in dem du lernst, bestimmt das Notensystem und die Sprache der Merkblätter. Die Website selbst gibt es auf Englisch, Französisch, Deutsch, Spanisch und Türkisch: Du wechselst die Sprache oben auf der Seite, bei der Anmeldung oder in den Einstellungen.",
        "landing.faq4q": "Wie viel Zeit kostet das pro Tag?",
        "landing.faq4a": "Was die Termine verlangen, kein Pensum. Der Plan nennt die Zeit jedes Tages, bevor du anfängst, oft zwischen zehn und fünfundzwanzig Minuten, mehr in der Prüfungswoche. Ein verpasster Tag verschiebt die Arbeit, er reißt kein Loch.",
        "landing.faq6q": "Und wenn ich schon Anki benutze?",
        "landing.faq6a": "Micabos verteilte Wiederholung ist die von Anki: vier Knöpfe, dieselben Intervalle, dieselben Stufen. Was Micabo hinzufügt, macht Anki nicht: das Merkblatt und die Karten aus deinem Kurs schreiben, einen Plan bis zum Prüfungsdatum anlegen und dich über Vorder- und Rückseite hinaus abfragen. Deine Anki-Stapel kannst du außerdem so importieren, wie sie sind.",
        "landing.iosEyebrow": "Die iPhone-App",
        "landing.iosTitleBefore": "Hol dir Micabo",
        "landing.iosTitleAccent": "aufs iPhone",
        "landing.iosSubtitle": "Die Website ist für den Schreibtisch gemacht: ein Skript ablegen, zwanzig Karten hintereinander korrigieren, Prüfungen in einen Kalender legen. Das Handy ist zum Lernen da — und das kann die App besser als jede Seite.",
        "landing.iosCta": "Im App Store laden",
        "landing.iosCtaNote": "Gleiches Konto, gleiche Kurse und gleicher Plan wie im Web.",
        "landing.iosPoint1Title": "Deine Kurse kommen mit",
        "landing.iosPoint1Body": "Was du am Rechner ablegst, ist schon da: das Merkblatt, die Karten und der Plan bis zum Prüfungstag.",
        "landing.iosPoint2Title": "Eine Lernrunde passt in jede Warteschlange",
        "landing.iosPoint2Body": "Ein Tippen zwischen dem Öffnen und der ersten Karte. Vier Knöpfe unter dem Daumen, und es geht dort weiter, wo du aufgehört hast.",
        "landing.iosPoint3Title": "Nichts wird zweimal gelernt",
        "landing.iosPoint3Body": "Eine Karte, die du am iPhone bewertest, kommt am nächsten Tag im Web nicht wieder: beide Seiten lesen denselben Plan.",
        "landing.iosScreenCaption": "Der Lernbildschirm, genau so, wie er sich öffnet.",
        "landing.iosPhoneAria": "Ein Blick in die iPhone-App",
        "landing.iosFullSite": "Im Web weitermachen",
