        "demo.retentionChartAria": "Zwei Merkkurven über {days} Tage. Ohne Wiederholung bleibt nach einem Monat fast nichts. Mit Micabo holt jede Wiederholung - an Tag {intervals} - alles auf hundert Prozent zurück, und der Abfall wird jedes Mal langsamer.",
        "demo.dayShort": "{n} T",
        "demo.courseTitle": "Wasserkreislauf",
        "demo.chapter": "Kapitel 4 · Wasser auf der Erde",
        "demo.raw1": "Der Wasserkreislauf umfasst alle Bewegungen des Wassers zwischen Meeren, Atmosphäre und Kontinenten.",
        "demo.raw2": "Durch die Sonnenstrahlung geht Oberflächenwasser in Dampf über; dieses Phänomen heißt Verdunstung und betrifft vor allem die Meere, die 71 % der Erdoberfläche bedecken.",
        "demo.raw3": "Der Wasserdampf steigt und trifft auf kältere Schichten; er kondensiert dann um Kondensationskerne und bildet Tröpfchen, die Wolken bilden.",
        "demo.raw4": "Werden die Tröpfchen zu schwer, fallen sie als Niederschlag, Regen oder Schnee je nach Temperatur im Fall.",
        "demo.raw5": "Ein Teil dieses Wassers fließt ab und erreicht Flüsse und dann die Meere; ein anderer versickert im Boden und speist das Grundwasser.",
        "demo.sheetParagraphMarked": "Wasser wechselt den Zustand, ohne den Planeten zu verlassen: was aus den Meeren **verdunstet**, fällt auf die Kontinente und kehrt zurück. ==71 % der Verdunstung kommt aus den Meeren.==",
        "demo.sheetCallout": "Regen oder Schnee hängt nicht von der Wolkenhöhe ab, sondern von der **Temperatur im Fall**.",
        "demo.sheetStep1": "Das Wasser der Meere verdunstet durch die Sonnenstrahlung.",
        "demo.sheetStep2": "Der Dampf kondensiert in der Höhe und bildet die Wolken.",
        "demo.sheetStep3": "Der Niederschlag gibt das Wasser an Land und Meer zurück.",
        "demo.rivers": "Die Flüsse bringen das Wasser zurück zum Meer",
        "demo.sheetHighlight": "71 % der Verdunstung kommt aus den Meeren.",
