        "copy.cards": "{count, plural, one {# Karte} other {# Karten}}",
        "copy.courses": "{count} Kurse",
        "copy.review": "Wiederholen",
        "copy.reviewCount": "{cards} wiederholen",
        "copy.sheetButton": "Blatt schreiben",
        "copy.cardsButton": "Karten erzeugen",
        "copy.audience": "{views, plural, one {# Aufruf} other {# Aufrufe}} · {adopts, plural, one {# Übernahme} other {# Übernahmen}}",
        "copy.practiceReview": "Ohne Zählen wiederholen",
        "copy.practiceReviewHint": "Ohne Zählen wiederholen · deine Fälligkeiten bleiben",
        "copy.heldBackNew": "{count, plural, one {# neue Karte für später — dein Tempo für heute ist erreicht.} other {# neue Karten für später — dein Tempo für heute ist erreicht.}}",
        "copy.alreadySubscribed": "Du hast schon ein Abo.",
        "legal.backHome": "Zurück zur Startseite",
        "legal.eyebrow": "Micabo · iPhone und Website",
        "legal.updated": "Zuletzt aktualisiert: {date}.",
        "legal.updatedDate": "2. September 2026",
        "legal.privacy.metaTitle": "Datenschutz",
        "legal.privacy.metaDescription": "Was Micabo von Ihnen behält, auf dem iPhone und auf der Website, und was Sie damit tun können.",
        "legal.privacy.heading": "Datenschutzrichtlinie",
        "legal.privacy.linkLabel": "Datenschutzrichtlinie",
        "legal.privacy.intro1": "Diese Richtlinie beschreibt die Daten, die Micabo verarbeitet, wenn Sie die Website [[site]] oder die iPhone-App (Kennung {bundle}) nutzen. Beide Clients teilen dasselbe Konto und dieselbe Datenbank. Sie gilt auch, wenn Sie noch kein Konto haben und die Website nur ansehen.",
        "legal.privacy.intro2": "Verantwortlich für die Verarbeitung ist {editor}. Für Fragen, Berichtigungen oder Löschungen: [[contact]].",
        "legal.privacy.whatTitle": "Was Micabo ist",
        "legal.privacy.whatBody": "Micabo verwandelt einen Kurs (PDF, Foto, Dokument, Video) in ein Merkblatt und in Karteikarten und lässt sie wiederkehren, bevor Sie sie vergessen. Ein Prüfungsmodus verdichtet die Wiederholungen vor einem Termin. Sie können einen Kurs mit Freunden teilen oder für sich behalten.",
        "legal.privacy.dataTitle": "Welche Daten wir verarbeiten",
        "legal.privacy.dataAccount": "**Das Konto.** E-Mail-Adresse, Kennungen von Apple oder Google, wenn Sie diese Anmeldung wählen, und ein Benutzername. Wir speichern Ihr Passwort nicht: die E-Mail-Anmeldung erfolgt über einen Link, nicht über ein Geheimnis, das wir behalten würden.",
        "legal.privacy.dataSchool": "**Der Bildungsweg.** Studienland, Stufe, Fächer, Einrichtung, wenn Sie sie angeben. Damit schreiben wir das Merkblatt in der richtigen Sprache und im richtigen System und zeigen Ihnen Kommilitonen derselben Einrichtung, wenn ein Kurs geteilt wird.",
        "legal.privacy.dataCourses": "**Ihre Kurse.** Die Dateien oder Links, die Sie ablegen, der daraus gelesene Text, die erzeugten Merkblätter und Karten, Schema-Bilder, Prüfungen (Name, Datum, Zielnote) und der Wiederholungsverlauf (wann eine Karte wiederkehrt, wie Sie sie bewertet haben).",
        "legal.privacy.dataFriends": "**Die Freunde.** Freundschaftsanfragen, Ihre Freundesliste und die Sichtbarkeit, die Sie jedem Kurs beim Import geben: nur Sie, Ihre Freunde oder die Kommilitonen Ihrer Einrichtung. Es gibt keinen öffentlichen Katalog, in dem ein Unbekannter auf Ihre Merkblätter stoßen würde.",
        "legal.privacy.dataSubscription": "**Das Abo.** Der Stand Ihres Pro-Zugangs (aktiv, Testphase, gekündigt), nicht Ihre Kartennummer. Die Zahlung nimmt Apple auf dem iPhone entgegen, Stripe auf der Website. RevenueCat hält das Recht, damit iPhone und Browser übereinstimmen.",
        "legal.privacy.dataWaitlist": "**Die Warteliste.** Wenn Sie Ihre Adresse hinterlassen, bevor Sie ein Konto haben, behalten wir sie, um Sie über die Öffnung zu informieren, zusammen mit der Seite, von der Sie kommen. Sie ist an kein Konto gebunden und in der App nicht sichtbar.",
        "legal.privacy.dataFeedback": "**Die Rückmeldungen.** Wenn Sie einen Fehler oder eine Idee aus der App senden, behalten wir die Nachricht, den Typ (Fehler oder Idee) und die Verbindung zu Ihrem Konto, um zu antworten. Sie bleiben 24 Monate und werden dann gelöscht. Sie dienen nicht dazu, Sie zu profilieren.",
        "legal.privacy.dataUsage": "**Die Nutzung der Generierungen.** Ein Zähler pro Tag und Funktion (Merkblatt, Karten, Erklärung), ohne den Inhalt des Kurses. Er dient dazu, Missbrauch zu begrenzen, nicht Sie zu profilieren.",
        "legal.privacy.dataDirectory": "**Das Verzeichnis.** Ihr Benutzername und, wenn Sie es angegeben haben, Ihre Einrichtung. Das sieht ein Freund oder ein Kommilitone, nicht Ihre E-Mail und nicht Ihre Einstellungen.",
        "legal.privacy.dataDevice": "**Was auf dem Gerät bleibt.** Auf dem iPhone können manche Teile (Okklusionsbilder, Audio einer Karte) das Telefon nie verlassen. Die Antworten des Begrüßungswegs bleiben zuerst auf dem Gerät und werden erst nach der Kontoeröffnung in die Datenbank geschrieben.",
        "legal.privacy.dataNoSell": "Wir verkaufen Ihre Daten nicht. Wir zeigen keine Werbung. Wir trainieren kein Sprachmodell auf Ihren Kursen, außer wenn eine ausdrückliche Einstellung das eines Tages anbietet — und diese Einstellung gibt es heute nicht.",
        "legal.privacy.whyTitle": "Warum wir sie verarbeiten",
        "legal.privacy.whyLead": "Die Rechtsgrundlagen im Sinne der DSGVO:",
        "legal.privacy.whyContract": "**Die Vertragserfüllung** — das Konto anlegen, einen Kurs importieren, Merkblatt und Karten schreiben, sie wiederholen, iPhone und Website synchronisieren, das Abo verwalten.",
        "legal.privacy.whyLegitimate": "**Das berechtigte Interesse** — den Dienst sichern, Missbrauch verhindern, eine Störung diagnostizieren, die Reichweite der Website in aggregierter Form messen und die Rückmeldungen lesen, die Sie uns senden. Dieses Interesse geht nicht vor Ihrem: die Trennung liegt in der Datenbank, nicht nur in der Anwendung.",
        "legal.privacy.whyLegal": "**Die gesetzliche Pflicht** — das aufzubewahren, was Abrechnung oder Buchhaltung verlangen, für die vorgeschriebene Zeit.",
        "legal.privacy.whyConsent": "**Die Einwilligung** — wenn Sie einen Kurs teilen, die Kamera öffnen oder sich mit Apple oder Google anmelden.",
        "legal.privacy.accessTitle": "Wer Zugriff hat",
        "legal.privacy.accessBody": "Ihre Kurse sind nur für Sie lesbar, außer Sie haben sie geteilt. Jede Anfrage an die Datenbank wird mit Ihrer Identität geprüft: es gibt keine Anfrage, die die Kurse eines anderen verlangen kann. Die Rückmeldungen, die Sie senden, liest das Team unter [[contact]]. Niemand sonst hat von der Anwendung aus Zugriff.",
        "legal.privacy.accessLead": "Dienstleister sehen einen Teil der Daten, ausschließlich um den Dienst zu erbringen:",
        "legal.privacy.accessSupabase": "**Supabase** (Europäische Union, Region Stockholm) — Konto, Datenbank, Dateien.",
        "legal.privacy.accessVercel": "**Vercel** — Hosting der Website, technische Protokolle (IP-Adresse, URL) und Reichweitenmessung: die Zahl der Seitenaufrufe, die Seite, von der Sie kommen, das Land und die Geräteart, ohne Cookie und ohne Kennung, die Ihnen folgt. Die Verarbeitung kann außerhalb der Europäischen Union stattfinden, unter den Standardvertragsklauseln des Anbieters.",
        "legal.privacy.accessApple": "**Apple und Google** — wenn Sie sich über sie anmelden oder im App Store zahlen.",
        "legal.privacy.accessStripe": "**Stripe** — Zahlung auf der Website.",
        "legal.privacy.accessRevenuecat": "**RevenueCat** — Abo-Stand, geteilt zwischen iPhone und Website.",
        "legal.privacy.accessFal": "**fal.ai und die Modelle, die es aufruft** (heute Sprachmodelle, insbesondere von Google) — der Text oder das Bild Ihres Kurses, für die Zeit, das Merkblatt oder die Karten zu schreiben. Sie dürfen sie für nichts anderes als diese Generierung verwenden.",
        "legal.privacy.accessYoutube": "**YouTube / Google** — wenn Sie ein Video importieren, lesen wir dessen Metadaten und Untertitel.",
        "legal.privacy.accessTransfer": "Einige dieser Dienstleister sind außerhalb der Europäischen Union niedergelassen. Die Übermittlung erfolgt dann nur, um den Dienst zu erbringen, und stützt sich auf die von der DSGVO vorgesehenen Garantien (Angemessenheitsbeschluss oder Standardvertragsklauseln des Anbieters).",
        "legal.privacy.cookiesTitle": "Cookies und Tracker",
        "legal.privacy.cookiesWeb": "Die Website setzt die für die Sitzung nötigen Cookies (Sie von einer Seite zur nächsten wiedererkennen, sobald Sie angemeldet sind) und ein Cookie für die Oberflächensprache (`micabo.ui_locale`), ein Jahr gültig, das Englisch, Französisch, Deutsch, Spanisch oder Türkisch merkt. Wir setzen kein Audience-Cookie, keine Werbung und kein standortübergreifendes Tracking. Die Website zählt ihre Besuche durchaus, schreibt dafür aber nichts auf Ihr Gerät: die Messung behält einen Seitenaufruf, dessen Herkunft, ein Land, eine Geräteart — und nichts, womit man Sie von einem Besuch zum nächsten oder auf einer anderen Website wiedererkennen könnte. Deshalb gibt es kein Einwilligungsbanner: auf dieser Seite gibt es nichts abzulehnen.",
        "legal.privacy.cookiesIos": "Das iPhone verwendet keine Cookies. Es bewahrt ein Sitzungstoken im Schlüsselbund des Geräts.",
        "legal.privacy.retentionTitle": "Wie lange wir sie behalten",
        "legal.privacy.retentionWhile": "Solange das Konto besteht. Rückmeldungen gehen spätestens nach 24 Monaten. Wenn Sie es löschen, unter Einstellungen auf der Website oder in der iPhone-App oder indem Sie uns schreiben, löschen wir das Profil, die Kurse (einschließlich des gelesenen Texts), die Merkblätter, die Karten, den Verlauf, die Prüfungen, die Freundschaften, die Nutzungszähler, die Rückmeldungen und die Adresse, die Sie gegebenenfalls auf der Warteliste hinterlassen haben.",
        "legal.privacy.retentionShared": "Ein Kurs, den Sie geteilt haben, verschwindet für Ihre Freunde, wenn Sie ihn löschen. Ein Freund, der Ihre Karten schon wiederholt hat, behält seinen eigenen Verlauf, nicht Ihr Dokument.",
        "legal.privacy.retentionAfter": "Nach der Löschung bleibt bei Dienstleistern, was das Gesetz oder ihr Vertrag verlangt: Stripe- oder Apple-Rechnungen, RevenueCat-Abo-Kennung, technische Protokolle (Vercel, Supabase) einige Wochen. fal.ai erhält den Text für die Zeit, das Merkblatt zu schreiben; wir verlangen nicht, dass es ihn behält.",
        "legal.privacy.rightsTitle": "Ihre Rechte",
        "legal.privacy.rightsBody": "Sie können auf Ihre Daten zugreifen, sie berichtigen, sie exportieren, einer Verarbeitung widersprechen oder die Löschung verlangen. Eine Kopie herunterladen: Einstellungen → „Meine Daten herunterladen“. Das Konto löschen: Einstellungen → „Konto löschen“, auf der Website oder in der iPhone-App. Sie können auch an [[contact]] schreiben. Wir antworten innerhalb eines Monats.",
        "legal.privacy.rightsCnil": "Sie können auch eine Beschwerde bei der CNIL einreichen (cnil.fr).",
        "legal.privacy.minorsTitle": "Minderjährige",
        "legal.privacy.minorsBody": "Micabo richtet sich an Studierende, auch in der Oberstufe. Wir fragen nicht nach dem Geburtsdatum. Wenn Sie unter fünfzehn sind, muss die Nutzung mit Zustimmung eines Sorgeberechtigten erfolgen. Wir verwenden die Daten eines Minderjährigen nicht für Werbung und nicht für ein kommerzielles Profiling.",
        "legal.privacy.iosTitle": "Das iPhone, zusätzlich zur Website",
        "legal.privacy.iosBody": "Die App kann den Zugriff auf Ihre Fotos oder die Kamera verlangen, um einen Kurs zu importieren. Das ist nicht Pflicht: die Website nimmt eine abgelegte Datei an. Benachrichtigungen, wenn Sie sie erlauben, dienen nur dazu, Sie an eine Wiederholung zu erinnern. Dasselbe Konto öffnet die App und die Website.",
        "legal.privacy.changesTitle": "Änderungen",
        "legal.privacy.changesBody": "Ändert sich diese Richtlinie wesentlich, aktualisieren wir das Datum am Seitenanfang. Die weitere Nutzung nach diesem Datum gilt für die neue Fassung, außer das Gesetz verlangt eine gesonderte Zustimmung.",
        "legal.privacy.changesAlso": "Die [[terms]] ergänzen diesen Text.",
        "legal.terms.metaTitle": "Nutzungsbedingungen",
        "legal.terms.metaDescription": "Die Regeln des Micabo-Dienstes für iPhone und Website: Konto, Kurse, Abo, Haftung.",
        "legal.terms.heading": "Nutzungsbedingungen",
        "legal.terms.linkLabel": "Nutzungsbedingungen",
        "legal.terms.intro1": "Diese Bedingungen regeln die Nutzung von Micabo — der Website [[site]] und der iPhone-App ({bundle}). Indem Sie ein Konto anlegen oder den Dienst nutzen, akzeptieren Sie sie. Wenn Sie nicht einverstanden sind, legen Sie kein Konto an.",
        "legal.terms.intro2": "Herausgeber ist {editor}. Kontakt: [[contact]].",
        "legal.terms.serviceTitle": "Der Dienst",
        "legal.terms.serviceBody": "Micabo liest ein Kursdokument, das Sie ablegen, und schreibt daraus ein Merkblatt und Karteikarten. Es lässt sie nach einer verteilten Wiederholung zurückkehren (dieselbe SM-2-Regel auf iPhone und Website). Sie können das Datum einer Prüfung setzen: der Wiederholungsplan verdichtet sich dann auf diesen Tag. Ein und dasselbe Konto öffnet beide Clients.",
        "legal.terms.servicePro": "Ein Teil des Dienstes ist ohne Abo zugänglich. Der Pro-Zugang (Kurse und Karten über die kostenlose Grenze hinaus, gemäß dem Angebot zum Zeitpunkt des Kaufs) ist kostenpflichtig.",
        "legal.terms.accountTitle": "Das Konto",
        "legal.terms.accountBody": "Sie können sich mit Apple, Google oder einem per E-Mail gesendeten Link anmelden. Sie sind für den Zugang zu Ihrem Postfach und zu diesen Drittkonten verantwortlich. Ein Konto pro Person.",
        "legal.terms.accountDelete": "Sie können das Konto unter Einstellungen löschen, auf der Website oder in der iPhone-App. Das löscht Ihre Kurse, Ihre Karten und Ihren Verlauf. Bereits von Apple oder Stripe eingenommene Käufe bleiben deren Erstattungsregeln unterworfen.",
        "legal.terms.coursesTitle": "Ihre Kurse",
        "legal.terms.coursesOwn": "Sie behalten das Eigentum an dem, was Sie ablegen. Sie geben uns nur das begrenzte und widerrufliche Recht, es zu lesen, zu speichern und in ein Merkblatt und in Karten zu verwandeln, um Ihnen den Dienst zu erbringen — einschließlich der Weitergabe an ein Sprachmodell für die Dauer der Generierung.",
        "legal.terms.coursesRights": "Sie legen nur Dokumente ab, die Sie nutzen dürfen. Ein Skript Ihres Dozenten, Ihre Notizen, ein Video, dessen Import erlaubt ist: ja. Ein ganzes abgeschriebenes Werk, die Arbeit eines anderen, ein rechtswidriger Inhalt: nein. Wir können einen Kurs entfernen oder ein Konto schließen, das diese Regel bricht.",
        "legal.terms.coursesShare": "Die Sichtbarkeit wird beim Import festgelegt. Ein privater Kurs bleibt bei Ihnen. Ein geteilter Kurs ist nur für die Personen sichtbar, die Sie gewählt haben (Freunde oder Kommilitonen der Einrichtung). Das ist keine für alle offene Bibliothek.",
        "legal.terms.notTitle": "Was Micabo nicht ist",
        "legal.terms.notBody": "Merkblatt und Karten werden automatisch erzeugt. Sie können sich irren, eine Stelle auslassen oder einen Scan falsch lesen. Micabo ist kein Lehrer und keine Notengarantie. Sie bleiben verantwortlich für das, was Sie lernen und am Prüfungstag abgeben.",
        "legal.terms.notInvent": "Wir bemühen uns, keine Definition zu erfinden, wenn das Dokument sie nicht trägt. Das macht das Ergebnis nicht unfehlbar.",
        "legal.terms.subTitle": "Das Abo",
        "legal.terms.subPrices": "Preise, Laufzeit und eine etwaige Probezeit sind die vor der Zahlung angezeigten. Sie können sich für neue Käufe ändern; ein laufendes Abo behält seine Bedingungen bis zur Verlängerung.",
        "legal.terms.subIos": "**Auf dem iPhone** läuft die Zahlung über den App Store. Kündigung, Verlängerung und Erstattungen folgen den Regeln von Apple. Verwalten Sie das Abo in den Einstellungen Ihres Apple-Kontos.",
        "legal.terms.subWeb": "**Auf der Website** läuft die Zahlung über Stripe. Die Kündigung erfolgt über den im Profil angegebenen Abrechnungsbereich oder indem Sie uns schreiben. Eine Probezeit, wenn sie angeboten wird, wird nur dann zur Zahlung, wenn Sie sie auslaufen lassen.",
        "legal.terms.subBoth": "Der auf der einen Seite gekaufte Pro-Zugang gilt auf der anderen: dasselbe Konto ist Pro auf dem iPhone und auf der Website. Ein Zahlungsvorfall kann eine Schonfrist öffnen; wir schließen den Zugang nicht in der ersten Stunde.",
        "legal.terms.forbidTitle": "Was Sie nicht tun",
        "legal.terms.forbidHarm": "Den Dienst nutzen, um jemandem zu schaden, zu belästigen oder auf eine Weise zu schummeln, die die Ordnung Ihrer Einrichtung verletzt.",
        "legal.terms.forbidAccess": "Versuchen, auf die Kurse eines anderen Kontos zuzugreifen, die Trennung zu umgehen oder den Dienst absichtlich zu überlasten.",
        "legal.terms.forbidResell": "Den Zugang weiterverkaufen, den Dienst über einen Roboter hinaus über normalen menschlichen Gebrauch auslesen oder Micabo kopieren, um aus unseren Generierungen ein Konkurrenzprodukt zu machen.",
        "legal.terms.forbidIllegal": "Rechtswidrige, hasserfüllte Inhalte ablegen oder solche, die die Privatsphäre anderer verletzen.",
        "legal.terms.availTitle": "Verfügbarkeit",
        "legal.terms.availBody": "Wir tun unser Möglichstes, damit iPhone und Website erreichbar bleiben. Eine Wartung, der Ausfall eines Dienstleisters (Hoster, Modell, Store) oder ein Generierungsfehler kann den Dienst unterbrechen. Wir bieten keine Garantie für schulische Ergebnisse und keine ununterbrochene Verfügbarkeit.",
        "legal.terms.liabilityTitle": "Haftung",
        "legal.terms.liabilityConsumer": "Wenn Sie Verbraucher sind, gelten Ihre gesetzlichen Rechte (Gewährleistung, Mediation, missbräuchliche Klauseln), und diese Bedingungen schließen sie nicht aus.",
        "legal.terms.liabilityLimit": "Darüber hinaus haftet Micabo nicht für erzielte Noten, ein unvollständiges Merkblatt, ein Vergessen am Prüfungstag oder einen indirekten Schaden (verlorene Zeit, verpasste Prüfung). Unsere Haftung, wenn sie für eine uns zurechenbare Pflichtverletzung festgestellt würde, ist auf den Betrag begrenzt, den Sie uns in den letzten zwölf Monaten gezahlt haben — außer bei grober Fahrlässigkeit, Vorsatz oder einer Verletzung der körperlichen Unversehrtheit.",
        "legal.terms.minorsTitle": "Minderjährige",
        "legal.terms.minorsBody": "Wenn Sie unter fünfzehn sind, muss ein Sorgeberechtigter diese Bedingungen akzeptieren und die Nutzung beaufsichtigen. Das Teilen eines Kurses mit Freunden bleibt in Ihrer Verantwortung und in der ihren.",
        "legal.terms.lawTitle": "Anwendbares Recht",
        "legal.terms.lawBody": "Diese Bedingungen unterliegen französischem Recht. Im Streitfall und nach einem schriftlichen Lösungsversuch an [[contact]] sind die französischen Gerichte zuständig — vorbehaltlich der Verbraucherschutzregeln, die für Sie günstiger wären.",
        "legal.terms.changesTitle": "Änderungen",
        "legal.terms.changesBody": "Wir können diese Bedingungen aktualisieren. Das Datum am Seitenanfang gilt. Eine Änderung, die den Preis eines laufenden Abos betrifft, wird Ihnen vor der Verlängerung mitgeteilt.",
        "legal.terms.changesAlso": "Die [[privacy]] beschreibt die Verarbeitung Ihrer Daten.",
        "articles.shared.navAria": "Seiten",
        "articles.shared.nextTitle": "Als Nächstes lesen",
        "articles.shared.ctaTitle": "Leg einen Kurs ab und sieh, was daraus wird.",
        "articles.shared.ctaBody": "Auf der Website wie auf dem iPhone, mit demselben Konto und demselben Plan.",
        "articles.method.metaTitle": "Die Methode: verteiltes Wiederholen und aktiver Abruf",
        "articles.method.metaDescription": "Ein Kurs, den man nur nachliest, bleibt nicht. Was man aus dem Gedächtnis holen muss, bleibt — vor allem, wenn die Frage kurz vor dem Vergessen wiederkommt. So wendet Micabo die Wiederholung an, mit den echten Abständen.",
        "articles.method.h1": "Nachlesen reicht nicht. Erinnern schon.",
        "articles.method.lead1": "Eine Seite, viermal gelesen, gibt das Gefühl, man könne sie — bis zur Klausur. Was wächst, ist Wiedererkennen: „ja, das habe ich schon gesehen“. Eine Prüfung fragt das nicht.",
        "articles.method.lead2": "Was hält, ist das, was man **aus dem Gedächtnis holen** musste, und das, was **kurz vor dem Vergessen** wiederkommt. Zwei alte Ideen, seit über einem Jahrhundert gemessen, und zu mühsam, sie von Hand zu halten. Das ist Micabos ganze Arbeit.",
        "articles.method.activeTitle": "Aktiver Abruf: die Frage vor der Antwort",
        "articles.method.active1": "Sich selbst zu prüfen wirkt mehr als Nachlesen, auch wenn man danebenliegt. Die Anstrengung des Abrufs festigt die Spur: eine Antwort, die man drei Sekunden sucht, wiegt mehr als eine, die man in einer liest.",
        "articles.method.active2": "Darum trägt eine Karte **eine Sache zum Abrufen**. Eine Karte mit fünf Punkten auf einmal lässt sich nicht benoten: man holt drei, und es gibt keinen Knopf für „drei Fünftel“.",
        "articles.method.spacingTitle": "Abstand: im letzten nützlichen Moment wiederkommen",
        "articles.method.spacing1": "Ohne Wiederholung bleibt von einem Kurs nach einem Monat fast nichts. Jeder Abruf setzt den Zähler auf hundert — und der Abfall danach ist **langsamer als der vorige**. Zur richtigen Zeit wiederholen kostet also nicht mehr Zeit: mit der Zeit weniger, weil das Gedächtnis sich festigt.",
        "articles.method.spacing2": "Nicht die Form jeder Kurve zählt, sondern **die Stelle, an der sie sich trennen**: die erste Wiederholung. Was die verteilte Wiederholung automatisiert, ist genau dieser Zeitpunkt, Karte für Karte.",
        "articles.method.plannerTitle": "Was Micabo bei jeder Note rechnet",
        "articles.method.planner1": "Micabo plant nach **SM-2**, Ankis Standardregel. Eine neue Karte geht durch kurze Stufen — {steps} — bevor sie in Tagen läuft. Danach multipliziert jede Note den Abstand mit einer Leichtigkeit, die bei {ease} startet und sich nach deinen Antworten bewegt.",
        "articles.method.planner2": "Vier Knöpfe, nicht zwei: „ich kann / ich kann nicht“ trennt nicht die mühsam geholte Karte von der, die von allein kam — und genau dieser Abstand entscheidet das nächste Datum. Das kündigen die vier Knöpfe auf einer neuen Karte an:",
        "articles.method.buttonsCaption": "Die Intervalle berechnet der Planer der App, sie sind nicht von Hand geschrieben.",
        "articles.method.planner3": "Der Abstand steht **vor** dem Tippen auf dem Knopf. Ein Planer, der im Verborgenen entscheidet, wird schnell manuell überstimmt: man tippt „leicht“, um schneller fertig zu sein, die Karte wandert drei Wochen weg, und man entdeckt sie am Prüfungstag neu.",
        "articles.method.stepMinutes": "{n} Min.",
        "articles.method.stepJoin": ", dann ",
        "articles.method.paceTitle": "Das Tempo: was die Last verlangt, keine Quote",
        "articles.method.pace1": "Micabo fragt weder nach einer Anzahl Karten pro Tag noch nach einem Minutenbudget. Es sieht, was die Termine heute verlangen, bedient alles davon und sagt, wie lange es dauern wird. Ein Studierender sieht etwa {seen} Karten in einer Stunde.",
        "articles.method.pace2": "Hier gab es einmal eine Obergrenze für neue Karten, kalibriert auf die {reps} Durchgänge, die eine Karte bis zum Sitzen braucht. Sie hatte einen entscheidenden Fehler: drei Tage vor einer Klausur lehnte sie Karten genau dieser Klausur im Namen des Tagestempos ab. Arbeit an dem Tag zurückzuhalten, an dem sie am meisten zählt, ist nicht die Aufgabe eines Planers.",
        "articles.method.paceNote": "Was der Plan verteilt, sind die Durchgänge bis zum Prüfungstag. Ein verpasster Tag hinterlässt also kein Loch: er verschiebt, und der Plan wird bei der nächsten Berechnung neu gebaut.",
        "articles.method.sheetTitle": "Zuerst das Merkblatt, dann die Karten",
        "articles.method.sheet1": "Eine Karteikarte setzt voraus, dass man schon verstanden hat. Sich zu einer ungelesenen Idee zu prüfen heißt, eine Antwort auswendig zu lernen, ohne zu wissen, wovon sie handelt — die Karte sitzt, die Prüfung nicht.",
        "articles.method.sheetFigure": "Das abgelegte Dokument wird **ein Merkblatt**: der Stoff in der richtigen Reihenfolge, die Stellen markiert, die zählen. Daraus kommen dann die Karten. Es ist dieselbe Merkblatt-Komponente wie in der App, am Demo-Kurs.",
        "articles.method.sheet2": "Darum schreibt Micabo zuerst **das Merkblatt** aus deinem Dokument: der Stoff in der richtigen Reihenfolge, die Stellen markiert, die zählen. Die Karten kommen aus diesem Blatt, nicht aus dem Rohtext. Du liest, dann prüfst du dich.",
        "articles.method.sheet3": "Micabo definiert nie einen Begriff, über den das Dokument nicht spricht. Ist der Kontext unklar, erscheint das zweifelhafte Wort nicht im Blatt: eine erfundene Definition klingt glaubwürdig — und genau das macht sie gefährlich.",
        "articles.method.formatsTitle": "Vier Arten, zum selben Merkblatt abgefragt zu werden",
        "articles.method.formats1": "Aktives Erinnern beschränkt sich nicht auf Vorder- und Rückseite. Zum selben Merkblatt stellt Micabo Quizfragen, Lückentexte und Karten und setzt bewertete Probeprüfungen zusammen. Die Fragen stammen aus deinen Unterlagen, und der Planer behandelt sie alle gleich: Eine gefundene Antwort schiebt die nächste weiter hinaus.",
        "articles.method.formatsFigure": "Ein Quiz erkennt man an seinen Punkten, einen Lückentext an seiner leeren Zeile, eine Karte an ihrer stummen Vorderseite. **Alle vier Formate kommen aus demselben Merkblatt** und werden auf derselben Skala bewertet.",
        "articles.method.limitsTitle": "Was die Methode nicht tut",
        "articles.method.limits1": "Verteiltes Wiederholen legt die Wiederholungen. Es versteht nicht für dich, schreibt keine Klausur, und rettet kein Kapitel, das gestern angefangen wurde — über eine Nacht gibt es keinen Abstand.",
        "articles.method.limits2": "Es ignoriert auch Daten, konstruktionsbedingt: SM-2 weiß nicht, dass in drei Wochen eine Prüfung ist. Genau das korrigiert der [[exam]].",
        "articles.method.examLink": "Prüfungsmodus",
        "articles.exam.metaTitle": "Prüfungsmodus: du nennst das Datum, der Plan zieht sich zusammen",
        "articles.exam.metaDescription": "Verteiltes Wiederholen kennt den Stichtag nicht. Micabos Prüfungsmodus gibt ihm eine Frist, rückt die Durchgänge zur Prüfung hin enger und lässt keine Karte darüber hinausgehen.",
        "articles.exam.h1": "Du nennst das Datum. Micabo ordnet alles neu.",
        "articles.exam.lead1": "Verteiltes Wiederholen legt jede Karte auf den letzten nützlichen Moment, ohne Ende. Es weiß nicht, dass am 14. eine Klausur ist. Eine heute als „leicht“ notierte Karte wandert drei Wochen weiter — auch wenn die Prüfung in zehn Tagen ist — und kommt nicht vorher zurück.",
        "articles.exam.lead2": "Der Prüfungsmodus gibt dem Planer, was ihm fehlt: **eine Frist** und die Note, die du anstrebst. Du setzt den Stichtag, er legt das Deck darum neu.",
        "articles.exam.trapTitle": "Warum ein normaler Plan in die Falle geht",
        "articles.exam.trap1": "Ein Deck aus zweihundert Karten in verteilter Wiederholung ist gut für laufende Tests und schlecht für ein festes Datum. Drei Dinge laufen schief: Karten fallen nach der Prüfung, andere wurden nie eingeführt, und die unsicheren kommen zu früh, um am Stichtag zu nützen.",
        "articles.exam.trap2": "Die Handlösung heißt: am Vorabend das ganze Deck. Genau das vermeidet die Methode: dreihundert Karten an einem Abend lassen am nächsten Tag nichts übrig, und das weiß man vorher.",
        "articles.exam.capTitle": "Keine Karte geht über den Stichtag hinaus",
        "articles.exam.cap1": "Das ist die Regel, die alles hält, und sie ist schärfer, als sie klingt. Während einer aktiven Prüfung ist der Abstand einer Karte **auf das Prüfungsdatum gedeckelt**.",
        "articles.exam.cap2": "Ohne diese Deckelung zerlegt die erste richtige Antwort den Plan: die Karte geht drei Wochen weg und aus dem Blick. Mit ihr kommt sie ein letztes Mal vor dem Stichtag. Die Abstände unter den Knöpfen sind deshalb kürzer als sonst, und die Sitzung sagt das oben — sonst wirkt der Planer kaputt.",
        "articles.exam.planTitle": "Der Plan, bevor er gilt",
        "articles.exam.plan1": "Micabo zeigt die Vorhersage **bevor** etwas verschoben wird: wie viele Karten abgedeckt sind, wie viele Durchgänge liegen, über wie viele Tage. Eine Umplanung, die man hinterher entdeckt, ist eine, die man rückgängig macht.",
        "articles.exam.plan2": "Die Last zieht sich zum Ende zusammen, ohne auf dem Vorabend zu stapeln: die letzten Durchgänge liegen auf den {days} letzten Tagen, von Karte zu Karte versetzt.",
        "articles.exam.dailyTitle": "Jeder Tag trägt eine benannte Aufgabe",
        "articles.exam.daily1": "Ein Plan, der „30 Minuten wiederholen“ sagt, unterscheidet sich nicht von einem Timer. Der von Micabo sagt, was zu tun ist: ein Quiz zu Kapitel 3, eine Probeprüfung, eine Erklärung laut, ein freier Tag. Du öffnest die App, und der Tag ist schon geschrieben.",
        "articles.exam.dailyFigure": "Der Plan liest sich in der Reihenfolge der Zeit, und die letzte Zeile ist die Prüfung. **Ein verpasster Tag verschiebt die Arbeit, er reißt kein Loch**: Der Plan wird bei der nächsten Berechnung neu gebaut.",
        "articles.exam.intensityTitle": "Drei Stärken, je nach der Note, die du willst",
        "articles.exam.intensityLead": "Wie oft jede Karte vor der Prüfung wiederkommen soll, ist nicht dieselbe Frage für „ich will bestehen“ und „ich will die Bestnote“. Du nennst die Zielnote, Micabo leitet die Stärke ab:",
        "articles.exam.intensityLight": "Leicht",
        "articles.exam.intensityStandard": "Normal",
        "articles.exam.intensityIntense": "Intensiv",
        "articles.exam.intensityPasses": "Durchgänge pro Karte",
        "articles.exam.intensityScale": "Die Notenskala folgt deinem Schulsystem: eine französische 20, eine Quebecer 100 und ein britisches A-Level lassen sich nicht vergleichen — und ein Regler, der überall gälte, gälte nirgendwo.",
        "articles.exam.severalTitle": "Mehrere Prüfungen, mehrere Kurse",
        "articles.exam.several1": "Eine Prüfung gilt für die Kurse, die du ihr gibst, und ein Kurs kann in mehreren Prüfungen liegen. Streiten sich zwei Daten um dieselbe Karte, deckelt **das nähere**: es ist die erste Grenze, und die zweite zuerst zu achten verfehlte beide.",
        "articles.exam.severalNote": "Nach dem Stichtag zwingt die Prüfung nicht mehr, und das Deck kehrt zum normalen Plan zurück. Nichts abzuschalten: ein vergangenes Datum ist keines mehr.",
        "articles.exam.limitsTitle": "Was der Prüfungsmodus nicht tut",
        "articles.exam.limits1": "Er macht keine Zeit. Eine Prüfung für morgen auf zweihundert neue Karten ergibt einen ehrlichen, unhaltbaren Plan — und Micabo zeigt ihn so, statt zu beruhigen.",
        "articles.exam.limits2": "Er ersetzt auch nicht die Methode: [[method]] tun die Arbeit, der Prüfungsmodus gibt ihnen nur eine Frist. Kommst du von Anki, sagt [[anki]] genau, was sich ändert.",
        "articles.exam.methodLink": "aktiver Abruf und Abstand",
        "articles.exam.ankiLink": "der Vergleich",
        "articles.anki.metaTitle": "Micabo oder Anki: was sich wirklich ändert",
        "articles.anki.metaDescription": "Anki ist offen, bewährt und ausgezeichnet. Micabo schreibt die Karten aus deinem Kurs und plant alles um ein Prüfungsdatum herum neu. Ein ehrlicher Vergleich, auch dort, wo Anki gewinnt.",
        "articles.anki.eyebrow": "Vergleich",
        "articles.anki.h1": "Micabo oder Anki: was sich wirklich ändert",
        "articles.anki.lead1": "Anki ist ein sehr gutes Programm. Es ist offen, hat zwanzig Jahre Erfahrung und eine Community, die alles dokumentiert hat. Wenn du es schon benutzt und es dir passt, hast du keinen Grund zu wechseln.",
        "articles.anki.lead2": "Der Unterschied liegt nicht in der Planung — **es ist dasselbe SM-2**. Er liegt davor, in der Zeit bis man Karten hat, und danach, wenn ein Prüfungsdatum fällt.",
        "articles.anki.tableTitle": "Zeile für Zeile",
        "articles.anki.tableLead": "Drei Zeilen gehen an Anki, und sie stehen so da, wie sie sind.",
        "articles.anki.tableCaption": "Vergleich von Micabo und Anki, Kriterium für Kriterium.",
        "articles.anki.colCriterion": "Kriterium",
        "articles.anki.rowAlgo": "Der Algorithmus",
        "articles.anki.rowAlgoMicabo": "SM-2, mit Ankis Standardeinstellungen.",
        "articles.anki.rowAlgoAnki": "Historisch SM-2, heute FSRS, und beides lässt sich einstellen.",
        "articles.anki.rowWrite": "Karten schreiben",
        "articles.anki.rowWriteMicabo": "Aus dem Kurs wird ein Merkblatt, aus dem Blatt werden Karten. Du liest nach und korrigierst.",
        "articles.anki.rowWriteAnki": "Deine Sache. Dort geht die meiste Zeit hin.",
        "articles.anki.rowDate": "Ein Prüfungsdatum",
        "articles.anki.rowDateMicabo": "Das Deck legt sich um den Stichtag neu, und nichts geht darüber hinaus.",
        "articles.anki.rowDateAnki": "Kein Begriff von einer Frist. Man schiebt das Deck von Hand vor.",
        "articles.anki.rowQuestions": "Die Arten der Abfrage",
        "articles.anki.rowQuestionsMicabo": "Karten, Quiz, Lückentexte, bewertete Probeprüfungen, laut erklären.",
        "articles.anki.rowQuestionsAnki": "Vorder- und Rückseite, und die Kartentypen, die man selbst baut.",
        "articles.anki.rowPlatforms": "Die Plattformen",
        "articles.anki.rowPlatformsMicabo": "iPhone und Browser, dasselbe Konto auf beiden Seiten.",
        "articles.anki.rowPlatformsAnki": "Rechner, Android, iPhone, Browser.",
        "articles.anki.rowDecks": "Fertige Decks",
        "articles.anki.rowDecksMicabo": "Kein Katalog. Deine Kurse, und die, die Freunde teilen.",
        "articles.anki.rowDecksAnki": "Tausende öffentliche Decks, von ungleicher Qualität.",
        "articles.anki.rowFriends": "Die Kurse deiner Kommilitonen",
        "articles.anki.rowFriendsMicabo": "Ein geteilter Kurs wird mit einer Geste übernommen und gehört dann dir.",
        "articles.anki.rowFriendsAnki": "Eine Datei, die man sich schickt.",
        "articles.anki.rowStart": "Der Einstieg",
        "articles.anki.rowStartMicabo": "Ein Dokument abgelegt, ein Blatt zu lesen, am Abend schon eine Sitzung.",
        "articles.anki.rowStartAnki": "Einstellungen, die man versteht, bevor die erste Karte kommt.",
        "articles.anki.costTitle": "Was Anki wirklich kostet: Zeit",
        "articles.anki.cost1": "Ein nützliches Anki-Deck für einen Unikurs sind zwei bis vier Stunden Tippen pro Kapitel: schneiden, eine Frage pro Idee, nicht fünf Punkte auf eine Karte. Die Arbeit lehrt etwas — das zu leugnen wäre unehrlich — aber es ist die Arbeit, wegen der man Anki im September öffnet und im November nicht mehr.",
        "articles.anki.costFigure": "Skript, Fotos, Word, PowerPoint, Video, Audio: **Alles kommt so rein, wie es ist**, und ein Anki-Stapel auch. Das Abtippen entfällt, das Nachlesen bleibt.",
        "articles.anki.cost2": "Micabo übernimmt diesen Schritt. Aus dem Kurs wird ein geordnetes Merkblatt, dann Karten aus diesem Blatt. Du liest nach, streichst das Falsche, löschst, was nicht nützt. Es bleibt deine Arbeit, aber sie beginnt beim Gegenlesen, nicht bei der leeren Seite.",
        "articles.anki.costNote": "Die Kehrseite ist echt: eine erzeugte Karte kann schlecht formuliert oder aus einem schlecht gelesenen Scan gezogen sein. Darum kommt das Blatt vor den Karten, und Micabo definiert keinen Begriff, über den das Dokument nicht spricht. Ein Blatt, das sich irrt, sieht nicht nach einem Fehler aus.",
        "articles.anki.dateTitle": "Was Anki nicht tut: das Datum",
        "articles.anki.date1": "Das ist der echte mechanische Unterschied. Verteiltes Wiederholen legt jede Karte auf den letzten nützlichen Moment, ohne Ende. Es weiß nicht, dass am 14. eine Klausur ist: eine als „leicht“ notierte Karte wandert drei Wochen und kommt nicht vor der Prüfung zurück.",
        "articles.anki.date2": "In Anki schiebt man das Deck von Hand vor oder wiederholt alles am Vorabend. In Micabo setzt du das Datum, und das Deck legt sich darum neu, mit einer Deckelung, die keine Karte über den Stichtag hinauslässt. [[exam]] sagt, wie.",
        "articles.anki.examLink": "Der Prüfungsmodus",
        "articles.anki.pickTitle": "Welches nehmen",
        "articles.anki.pickAnki": "**Bleib bei Anki**, wenn du deinen Planer gern selbst einstellst, wenn du FSRS willst, wenn du auf Android bist, oder wenn dir ein offenes Werkzeug wichtig ist, dessen Dateien dir gehören.",
        "articles.anki.pickMicabo": "**Versuch Micabo**, wenn nicht das Wiederholen blockiert, sondern das Herstellen der Karten — oder wenn deine Wiederholungen um Prüfungsdaten kreisen, nicht um einen Dauerfluss.",
        "articles.anki.pickBoth": "Und wenn du schwankst: [[method]] ist in beiden dieselbe. Sie tut die Arbeit, nicht das Programm, das sie trägt.",
        "articles.anki.methodLink": "die Methode",
    ]

