        "landing.step1Title": "Pones la fecha, y la nota a la que aspiras.",
        "landing.step1Body": "Un parcial dentro de tres semanas con un sobresaliente en mente no pide el mismo trabajo que un control dentro de diez días que solo hay que aprobar. Micabo parte de ahí y deduce cuántas veces tiene que volver cada tarjeta.",
        "landing.step2Title": "Dejas todo lo que anda suelto alrededor del examen.",
        "landing.step2Body": "PDF de apuntes, fotos de la clase, Word, PowerPoint, vídeo de YouTube, grabación de las prácticas, mazo de Anki. Nada que preparar: todo entra tal cual, y Micabo lo lee todo.",
        "landing.step3Title": "Micabo escribe la ficha, y luego saca las tarjetas.",
        "landing.step3Body": "La clase queda en orden, los pasajes que importan marcados, y las tarjetas salen de esa ficha. Lees, corriges lo que está mal, borras lo que no sirve.",
        "landing.step4Title": "El plan se arma día a día, hasta el día del examen.",
        "landing.step4Body": "Cada jornada lleva un trabajo con nombre: un test sobre el capítulo 3, un simulacro, un descanso. Abres la app y sabes qué hacer. La carga se concentra al acercarse la prueba, y ninguna tarjeta se va más allá.",
        "landing.step5Title": "Te preguntan de cuatro maneras.",
        "landing.step5Body": "Simulacro puntuado, test, tarjetas, texto con hueco. Las preguntas salen de tus documentos, no de un banco genérico, y cada respuesta decide la fecha de la siguiente.",
