        "landing.methodMore": "Leer el método en detalle",
        "landing.examEyebrow": "Modo examen",
        "landing.examTitle": "El plan se concentra al acercarse la prueba.",
        "landing.examNote": "La repetición espaciada ignora el día del examen. El modo examen le da una fecha límite: los últimos repasos caen en los últimos días, y ninguna tarjeta se va más allá. El calendario de abajo lo calcula el planificador de la app.",
