        "landing.footerApp": "En la app",
        "landing.footerCards": "Las tarjetas",
        "landing.faq1q": "¿Mis cursos son privados?",
        "landing.faq1a": "Sí. Tus cursos no aparecen en ningún catálogo. Por defecto solo los ves tú, y puedes compartir uno al importarlo, con tus amigos o con nadie. La separación está en la base de datos: cada petición se evalúa con tu identidad, así que no existe ninguna petición que pueda pedir los cursos de otra persona.",
        "landing.faq2q": "¿Micabo se inventa cosas?",
        "landing.faq2a": "Es el riesgo que nos tomamos más en serio, porque una ficha falsa no parece un error. Una palabra mal leída por el reconocimiento de texto puede dar una definición perfectamente creíble y completamente falsa. Por eso Micabo nunca define un término del que no está seguro: cuando el contexto no decide, la palabra dudosa simplemente no aparece en la ficha.",
        "landing.faq3q": "¿Funciona en otros idiomas? ¿Otros sistemas escolares?",
        "landing.faq3a": "Sí. El país donde estudias decide el sistema de notas y el idioma de las fichas. El sitio, por su parte, se lee en inglés, francés, alemán, español o turco: cambias el idioma arriba de la página, en el registro o en los ajustes.",
        "landing.faq4q": "¿Cuánto tiempo lleva al día?",
        "landing.faq4a": "Lo que piden las fechas, no una cuota. El plan anuncia el tiempo de cada jornada antes de que empieces, a menudo entre diez y veinticinco minutos, más en la semana del examen. Un día perdido desplaza el trabajo, no abre un agujero.",
        "landing.faq6q": "¿Y si ya uso Anki?",
        "landing.faq6a": "La repetición espaciada de Micabo es la de Anki: cuatro botones, los mismos intervalos, los mismos escalones. Lo que Micabo añade, Anki no lo hace: escribir la ficha y las tarjetas a partir de tu clase, armar un plan hasta la fecha del examen y preguntarte más allá del anverso y el reverso. También puedes importar tus mazos de Anki tal cual.",
        "landing.iosEyebrow": "La app para iPhone",
        "landing.iosTitleBefore": "Descarga Micabo",
        "landing.iosTitleAccent": "en tu iPhone",
        "landing.iosSubtitle": "La web está hecha para el escritorio: subir unos apuntes, corregir veinte tarjetas seguidas, colocar los exámenes en un calendario. El móvil es para repasar — y eso lo hace mejor la app que cualquier página.",
        "landing.iosCta": "Descargar en el App Store",
        "landing.iosCtaNote": "La misma cuenta, los mismos cursos y el mismo plan que en la web.",
        "landing.iosPoint1Title": "Tus apuntes te siguen",
        "landing.iosPoint1Body": "Lo que subes desde el ordenador ya está ahí: la ficha, las tarjetas y el plan hasta el día del examen.",
        "landing.iosPoint2Title": "Un repaso cabe en una cola",
        "landing.iosPoint2Body": "Un toque entre abrir la app y la primera tarjeta. Cuatro botones bajo el pulgar, y sigue donde lo dejaste.",
        "landing.iosPoint3Title": "Nada se repasa dos veces",
        "landing.iosPoint3Body": "Una tarjeta que calificas en el iPhone no vuelve al día siguiente en la web: los dos lados leen el mismo plan.",
        "landing.iosScreenCaption": "La pantalla de repaso, tal y como se abre.",
        "landing.iosPhoneAria": "Vistazo a la app para iPhone",
        "landing.iosFullSite": "Seguir en la web",
