        "demo.courseTitle": "El ciclo del agua",
        "demo.chapter": "Capítulo 4 · El agua en la Tierra",
        "demo.raw1": "El ciclo del agua designa el conjunto de movimientos del agua entre los océanos, la atmósfera y los continentes.",
        "demo.raw2": "Por la radiación solar el agua de superficie pasa a vapor; este fenómeno se llama evaporación y afecta sobre todo a los océanos, que cubren el 71 % de la superficie terrestre.",
        "demo.raw3": "El vapor de agua sube y encuentra capas más frías; entonces se condensa alrededor de núcleos de condensación para formar gotas que constituyen las nubes.",
        "demo.raw4": "Cuando las gotas se vuelven demasiado pesadas caen en forma de precipitaciones, lluvia o nieve según la temperatura durante la caída.",
        "demo.raw5": "Una parte de esta agua escurre y llega a los ríos y luego a los océanos; otra se infiltra en el suelo y alimenta los acuíferos.",
        "demo.sheetParagraphMarked": "El agua cambia de estado sin dejar el planeta: lo que se **evapora** de los océanos cae en los continentes y vuelve. ==El 71 % de la evaporación viene de los océanos.==",
