        "landing.faq1q": "Derslerim gizli mi?",
        "landing.faq1a": "Evet. Derslerin hiçbir katalogda görünmez. Varsayılan olarak onları yalnızca sen görürsün ve içe aktarırken birini arkadaşlarınla ya da hiç kimseyle paylaşabilirsin. Ayrım veritabanındadır: her istek senin kimliğinle değerlendirilir, dolayısıyla başkasının derslerini isteyebilecek bir istek yoktur.",
        "landing.faq2q": "Micabo bir şeyler uyduruyor mu?",
        "landing.faq2a": "En ciddiye aldığımız risk bu, çünkü yanlış bir özet bir hataya benzemez. Metin tanımanın yanlış okuduğu bir kelime tamamen inandırıcı ve tamamen yanlış bir tanım verebilir. Bu yüzden Micabo emin olmadığı bir terimi asla tanımlamaz: bağlam karar vermiyorsa, şüpheli kelime özette hiç görünmez.",
        "landing.faq3q": "Başka dillerde çalışıyor mu? Başka okul sistemlerinde?",
        "landing.faq3a": "Evet. Okuduğun ülke not sistemine ve özetlerin diline karar verir. Site ise İngilizce, Fransızca, Almanca, İspanyolca veya Türkçe okunur: dili sayfanın üstünden, kayıt sırasında ya da ayarlardan değiştirirsin.",
        "landing.faq4q": "Günde ne kadar zaman alır?",
        "landing.faq4a": "Kota değil, tarihlerin istediği kadar. Plan her günün süresini sen başlamadan önce söyler, çoğu zaman on ile yirmi beş dakika arası, sınav haftasında daha fazla. Kaçırılan bir gün işi kaydırır, boşluk açmaz.",
        "landing.faq6q": "Ya zaten Anki kullanıyorsam?",
        "landing.faq6a": "Micabo'nun aralıklı tekrarı Anki'ninkidir: dört düğme, aynı aralıklar, aynı basamaklar. Micabo'nun eklediğini Anki yapmaz: dersinden özeti ve kartları yazmak, sınav tarihine kadar bir plan kurmak ve seni ön-arka yüzün ötesinde sorgulamak. Anki destelerini de olduğu gibi içe aktarabilirsin.",
        "landing.iosEyebrow": "iPhone uygulaması",
        "landing.iosTitleBefore": "Micabo'yu iPhone'una",
        "landing.iosTitleAccent": "indir",
        "landing.iosSubtitle": "Site masa başı için yapıldı: ders notu yüklemek, arka arkaya yirmi kartı düzeltmek, sınavları takvime yerleştirmek. Telefon ise tekrar içindir — ve bunu hiçbir sayfa uygulamadan iyi yapamaz.",
        "landing.iosCta": "App Store'dan indir",
        "landing.iosCtaNote": "Web'dekiyle aynı hesap, aynı dersler ve aynı plan.",
        "landing.iosPoint1Title": "Derslerin yanında",
        "landing.iosPoint1Body": "Bilgisayardan yüklediğin her şey orada: özet, kartlar ve sınav gününe kadar uzanan plan.",
        "landing.iosPoint2Title": "Bir tekrar sıra beklerken biter",
        "landing.iosPoint2Body": "Uygulamayı açmakla ilk kart arasında tek dokunuş. Başparmağının altında dört düğme, ve kaldığın yerden devam eder.",
        "landing.iosPoint3Title": "Hiçbir şey iki kez çalışılmaz",
        "landing.iosPoint3Body": "iPhone'da değerlendirdiğin bir kart ertesi gün web'de geri gelmez: iki taraf da aynı planı okur.",
        "landing.iosScreenCaption": "Tekrar ekranı, açıldığı haliyle.",
        "landing.iosPhoneAria": "iPhone uygulamasına bir bakış",
        "landing.iosFullSite": "Web'de devam et",
